import type { Item, SlotSpec, Tier } from '../data/types.ts';
import { openRoster, slotSuits } from '../data/types.ts';
import type { Action, Award, GameConfig, GameState, ItemMode, Player, PlayerId } from './types.ts';
import { MAX_PLAYERS, MIN_PLAYERS } from './types.ts';

/**
 * The whole rulebook, as one pure reducer. No Svelte, DOM or storage.
 *
 * Invalid actions return the state untouched rather than throwing, so a stray
 * double-tap can't wedge a game.
 */

export const DEFAULT_BUDGET = 20;
export const DEFAULT_SLOTS = 5;
export const MIN_BID = 1;
/** Longest player name: what still fits the player panels and bid buttons on a small phone. */
export const NAME_MAX = 12;

export const cleanName = (name: string): string => name.trim().slice(0, NAME_MAX).trim();

/** The opponent in a two-player game. Bot and pass-and-play code only. */
export const other = (id: PlayerId): PlayerId => (id === 0 ? 1 : 0);

/** Every seat in the game, in order. */
export const seats = (state: GameState): PlayerId[] => state.players.map((player) => player.id);

/** The first of `candidates` at or after `from`, going round the table. */
function nextFrom(state: GameState, from: PlayerId, candidates: PlayerId[]): PlayerId {
	const count = state.players.length;
	const order = state.players.map((_, step) => (from + step) % count);
	// Candidates are always seats, so this only falls through when there are none.
	return order.find((id) => candidates.includes(id)) ?? 0;
}

function blankPlayer(id: PlayerId, name: string, money: number): Player {
	return { id, name, money, roster: [] };
}

export function defaultConfig(): GameConfig {
	return {
		budget: DEFAULT_BUDGET,
		slots: DEFAULT_SLOTS,
		roster: openRoster(DEFAULT_SLOTS),
		positional: false,
		categoryId: '',
		variantId: '',
		categoryLabel: '',
		variantLabel: null
	};
}

export function initialState(): GameState {
	return {
		phase: 'setup',
		config: defaultConfig(),
		players: [
			blankPlayer(0, 'Player 1', DEFAULT_BUDGET),
			blankPlayer(1, 'Player 2', DEFAULT_BUDGET)
		],
		deck: [],
		index: 0,
		bid: null,
		freeTurn: 0,
		lastAward: null,
		history: []
	};
}

/* ------------------------------------------------------------------ *
 * Slots
 * ------------------------------------------------------------------ */

export function currentItem(state: GameState): Item | null {
	return state.deck[state.index] ?? null;
}

export function openSlots(state: GameState, id: PlayerId): SlotSpec[] {
	const filled = new Set(state.players[id].roster.map((entry) => entry.slotId));
	return state.config.roster.filter((slot) => !filled.has(slot.id));
}

/** Default landing slot: the one it suits, else the first open one. `assign` can move it. */
export function defaultSlotFor(state: GameState, id: PlayerId, item: Item): SlotSpec | null {
	const open = openSlots(state, id);
	return open.find((slot) => slotSuits(slot, item)) ?? open[0] ?? null;
}

/** Any item fits any open slot, so this is purely "do they have room left". */
export function canReceive(state: GameState, id: PlayerId, item: Item): boolean {
	return defaultSlotFor(state, id, item) !== null;
}

export function slotsLeft(state: GameState, id: PlayerId): number {
	return openSlots(state, id).length;
}

export function isBroke(state: GameState, id: PlayerId): boolean {
	return state.players[id].money <= 0;
}

/** Players with a slot left for the current item. */
export function needers(state: GameState): PlayerId[] {
	const item = currentItem(state);
	return item ? seats(state).filter((id) => canReceive(state, id, item)) : [];
}

/** Players who can bid on the current item: room left and money left. */
export function bidders(state: GameState): PlayerId[] {
	return needers(state).filter((id) => !isBroke(state, id));
}

/**
 * Which rule governs the current item. A full roster outranks the money rules,
 * and with more than two players the broke ones sit an auction out.
 */
export function itemMode(state: GameState): ItemMode {
	if (needers(state).length <= 1) return 'forced';
	const solvent = bidders(state).length;
	if (solvent >= 2) return 'contest';
	return solvent === 1 ? 'solo' : 'alternate';
}

/** In `solo` mode, the player who still has money to spend. */
export function solventPlayer(state: GameState): PlayerId {
	return bidders(state)[0] ?? 0;
}

/** Who receives a free award. Several candidates take turns, from `freeTurn`. */
export function freeRecipient(state: GameState): PlayerId {
	const mode = itemMode(state);
	const open = needers(state);

	if (mode === 'forced') return open[0] ?? 0;
	if (mode === 'solo') {
		const broke = open.filter((id) => isBroke(state, id));
		return nextFrom(state, state.freeTurn, broke);
	}
	return nextFrom(state, state.freeTurn, open);
}

/** Bidders still in on this item: neither holding the bid nor dropped out. */
export function stillToAnswer(state: GameState): PlayerId[] {
	const bid = state.bid;
	if (!bid) return bidders(state);
	return bidders(state).filter((id) => id !== bid.holder && !bid.passed?.includes(id));
}

/** Smallest legal bid right now: $1 to open, else a dollar over the standing bid. */
export function minBid(state: GameState): number {
	return state.bid ? state.bid.amount + 1 : MIN_BID;
}

/** Capped only by the wallet — no reserve, per rule 6. */
export function maxBid(state: GameState, id: PlayerId): number {
	return state.players[id].money;
}

export function canBid(state: GameState, id: PlayerId, amount: number): boolean {
	if (state.phase !== 'resolve' || itemMode(state) !== 'contest') return false;
	// You can't raise your own standing bid, or come back once you've passed.
	if (state.bid?.holder === id || state.bid?.passed?.includes(id)) return false;
	if (!bidders(state).includes(id)) return false;
	if (!Number.isInteger(amount)) return false;
	return amount >= minBid(state) && amount <= maxBid(state, id);
}

/**
 * Whether `id` may stop raising. Not the holder: accepting your own bid would be
 * a self-serve win button. Once every other bidder has passed, the item is sold.
 */
export function canSell(state: GameState, id: PlayerId): boolean {
	if (state.phase !== 'resolve' || itemMode(state) !== 'contest') return false;
	if (!state.bid) return false;
	return stillToAnswer(state).includes(id);
}

export function canBuy(state: GameState, id: PlayerId, amount: number): boolean {
	if (state.phase !== 'resolve' || itemMode(state) !== 'solo') return false;
	if (id !== solventPlayer(state)) return false;
	if (!Number.isInteger(amount)) return false;
	return amount >= MIN_BID && amount <= maxBid(state, id);
}

export function totalSpent(player: Player): number {
	return player.roster.reduce((sum, entry) => sum + entry.price, 0);
}

export function rosterFull(state: GameState, id: PlayerId): boolean {
	return slotsLeft(state, id) === 0;
}

export function isGameOver(state: GameState): boolean {
	return seats(state).every((id) => rosterFull(state, id));
}

/** 1-based position in the deck, for the "Item 3 of 10" readout. */
export function itemNumber(state: GameState): number {
	return Math.min(state.index + 1, state.deck.length);
}

/** The roster entry filling a slot, for the slot-by-slot roster views. */
export function entryInSlot(
	state: GameState,
	id: PlayerId,
	slotId: string
): GameState['players'][number]['roster'][number] | undefined {
	return state.players[id].roster.find((entry) => entry.slotId === slotId);
}

/* ------------------------------------------------------------------ *
 * Rebalancing
 * ------------------------------------------------------------------ */

const TIER_RANK: Record<Tier, number> = { bad: 0, mid: 1, good: 2, great: 3 };

/** Which card fills each slot in a largest natural pairing (Kuhn's augmenting paths). */
function naturalMatching(cards: readonly Item[], slots: readonly SlotSpec[]): (number | null)[] {
	const holder: (number | null)[] = slots.map(() => null);
	const place = (card: number, seen: Set<number>): boolean => {
		for (let s = 0; s < slots.length; s++) {
			if (seen.has(s) || !slotSuits(slots[s], cards[card])) continue;
			seen.add(s);
			const held = holder[s];
			if (held === null || place(held, seen)) {
				holder[s] = card;
				return true;
			}
		}
		return false;
	};
	for (let card = 0; card < cards.length; card++) place(card, new Set());
	return holder;
}

const matched = (holder: (number | null)[]) => holder.filter((card) => card !== null).length;

/**
 * Keeps every open slot fillable by someone who plays it. When the rest of the
 * deck can no longer cover a slot (both QBs went to one roster, say), the card
 * about to be revealed is swapped for a bench player who fits, at the tier the
 * deck dealt. Only a card the deck can spare is swapped, so nobody else's slot
 * is stranded by the fix. Placement stays free; this only changes what's dealt.
 */
function rebalance(state: GameState): GameState {
	const bench = state.bench ?? [];
	const current = currentItem(state);
	if (bench.length === 0 || !current) return state;

	const slots = seats(state).flatMap((id) => openSlots(state, id));
	const cards = state.deck.slice(state.index);
	const best = matched(naturalMatching(cards, slots));
	if (best === slots.length) return state;

	const rest = naturalMatching(cards.slice(1), slots);
	if (matched(rest) < best) return state;

	const needed = slots.filter((_, s) => rest[s] === null);
	const rank = TIER_RANK[current.tier];
	// Same tier first, then the nearest one, leaning up rather than down.
	const distance = (item: Item) =>
		Math.abs(TIER_RANK[item.tier] - rank) * 2 + (TIER_RANK[item.tier] < rank ? 1 : 0);
	const swap = bench
		.filter((item) => needed.some((slot) => slotSuits(slot, item)))
		.reduce<Item | null>(
			(pick, item) => (!pick || distance(item) < distance(pick) ? item : pick),
			null
		);
	if (!swap) return state;

	return {
		...state,
		deck: state.deck.map((item, i) => (i === state.index ? swap : item)),
		bench: [...bench.filter((item) => item.id !== swap.id), current]
	};
}

/* ------------------------------------------------------------------ *
 * Reducer
 * ------------------------------------------------------------------ */

function replacePlayer(state: GameState, id: PlayerId, next: Player): Player[] {
	return state.players.map((player) => (player.id === id ? next : player));
}

/** The single place money leaves a wallet and a roster slot gets consumed. */
function awardCurrent(
	state: GameState,
	playerId: PlayerId,
	price: number,
	options: { free: boolean; declined?: boolean }
): GameState {
	const item = currentItem(state);
	if (!item) return state;

	const slot = defaultSlotFor(state, playerId, item);
	if (!slot) return state;

	const winner = state.players[playerId];
	const charge = options.free ? 0 : price;
	if (charge > winner.money) return state;

	const award: Award = {
		playerId,
		item,
		price: charge,
		free: options.free,
		mode: itemMode(state),
		declined: options.declined ?? false,
		slotId: slot.id,
		slotLabel: slot.label
	};

	const updated: Player = {
		...winner,
		money: winner.money - charge,
		roster: [...winner.roster, { item, price: charge, free: options.free, slotId: slot.id }]
	};

	return {
		...state,
		phase: 'award',
		players: replacePlayer(state, playerId, updated),
		bid: null,
		lastAward: award,
		history: [...state.history, award]
	};
}

export function applyAction(state: GameState, action: Action): GameState {
	switch (action.type) {
		case 'start': {
			const names = action.names.slice(0, MAX_PLAYERS);
			while (names.length < MIN_PLAYERS) names.push('');
			return {
				...initialState(),
				phase: 'reveal',
				config: action.config,
				players: names.map((name, id) =>
					blankPlayer(id, cleanName(name) || `Player ${id + 1}`, action.config.budget)
				),
				deck: action.deck,
				bench: action.bench ?? []
			};
		}

		case 'reveal': {
			if (state.phase !== 'reveal') return state;
			return { ...state, phase: 'resolve' };
		}

		case 'bid': {
			if (!canBid(state, action.player, action.amount)) return state;
			const passed = state.bid?.passed;
			return {
				...state,
				bid: { amount: action.amount, holder: action.player, ...(passed ? { passed } : {}) }
			};
		}

		case 'sold': {
			// A standing bid is required, which is what makes opening mandatory: with
			// 2xN items and N slots each, every item has to find an owner. The second
			// test only narrows the type — `canSell` already requires a bid.
			const bid = state.bid;
			if (!canSell(state, action.player) || !bid) return state;
			if (stillToAnswer(state).length > 1) {
				return { ...state, bid: { ...bid, passed: [...(bid.passed ?? []), action.player] } };
			}
			return awardCurrent(state, bid.holder, bid.amount, { free: false });
		}

		case 'buy': {
			if (!canBuy(state, action.player, action.amount)) return state;
			return awardCurrent(state, action.player, action.amount, { free: false });
		}

		case 'decline': {
			if (state.phase !== 'resolve' || itemMode(state) !== 'solo') return state;
			if (action.player !== solventPlayer(state)) return state;
			// Rule 7: nobody bought it, so a broke player takes it for nothing.
			const recipient = freeRecipient(state);
			const next = awardCurrent(state, recipient, 0, { free: true, declined: true });
			// Two broke players or more take turns at the freebies.
			if (next === state || state.players.length === 2) return next;
			return { ...next, freeTurn: (recipient + 1) % state.players.length };
		}

		case 'claim': {
			if (state.phase !== 'resolve') return state;
			const mode = itemMode(state);
			if (mode !== 'alternate' && mode !== 'forced') return state;

			const recipient = freeRecipient(state);
			const next = awardCurrent(state, recipient, 0, { free: true });
			if (next === state) return state;
			// Rule 8's alternation advances only on alternating awards.
			return mode === 'alternate'
				? { ...next, freeTurn: (recipient + 1) % state.players.length }
				: next;
		}

		case 'assign': {
			// Re-slots the pick just won, while the award is still on screen.
			if (state.phase !== 'award' || !state.lastAward) return state;
			const award = state.lastAward;
			const target = state.config.roster.find((slot) => slot.id === action.slotId);
			if (!target || target.id === award.slotId) return state;

			const player = state.players[award.playerId];
			const taken = player.roster.some(
				(entry) => entry.slotId === target.id && entry.item.id !== award.item.id
			);
			if (taken) return state;

			const roster = player.roster.map((entry) =>
				entry.item.id === award.item.id ? { ...entry, slotId: target.id } : entry
			);
			const moved: Award = { ...award, slotId: target.id, slotLabel: target.label };

			return {
				...state,
				players: replacePlayer(state, award.playerId, { ...player, roster }),
				lastAward: moved,
				history: [...state.history.slice(0, -1), moved]
			};
		}

		case 'next': {
			if (state.phase !== 'award') return state;
			const index = state.index + 1;
			const done = index >= state.deck.length;
			return rebalance({
				...state,
				phase: done ? 'results' : 'reveal',
				index,
				bid: null,
				lastAward: done ? state.lastAward : null
			});
		}

		case 'reset':
			return initialState();

		default:
			return state;
	}
}
